// Shadow deployment: mirror real traffic to V2, return only V1, diff responses.
package com.bank.gateway.demo;

import java.math.BigDecimal;
import java.util.logging.*;

public class ShadowDemo {
    private static final Logger log = Logger.getLogger("Shadow");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new ShLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        MirroringGateway gateway = new MirroringGateway();

        log.info("=== Mirroring real requests to shadow V2 ===");
        gateway.handle(new InterestRequest("SAV2001", new BigDecimal("1000000"), new BigDecimal("3.0")));
        gateway.handle(new InterestRequest("CUR3001", new BigDecimal("250000"), new BigDecimal("3.0")));
        gateway.handle(new InterestRequest("ACC4005", new BigDecimal("0"), new BigDecimal("3.0"))); // edge case
        gateway.handle(new InterestRequest("ACC4006", new BigDecimal("500000"), new BigDecimal("6.5")));

        log.info("=== Shadow comparison report ===");
        gateway.report();
    }
}

// ─── Would be in core/InterestRequest.java ───
class InterestRequest {
    final String accountId; final BigDecimal principal; final BigDecimal ratePct;
    InterestRequest(String accountId, BigDecimal principal, BigDecimal ratePct) {
            this.accountId = accountId;
            this.principal = principal
            this.ratePct = ratePct;
    }
}

// ─── Would be in core/InterestResponse.java ───
class InterestResponse {
    final String accountId; final BigDecimal interest;
        InterestResponse(String accountId, BigDecimal interest) { this.accountId = accountId;
        this.interest = interest; }
    @Override public boolean equals(Object o) {
        if (!(o instanceof InterestResponse)) return false;
        InterestResponse r = (InterestResponse) o;
        return accountId.equals(r.accountId) && interest.compareTo(r.interest) == 0;
    }
    @Override public String toString() { return accountId + "=Rs." + interest; }
}

// ─── Would be in service/InterestServiceV1.java (LIVE) ───
class InterestServiceV1 {
    // live writes to the REAL ledger and sends REAL notifications (not shown here)
    InterestResponse compute(InterestRequest req) {
        BigDecimal interest = req.principal.multiply(req.ratePct)
                .divide(new BigDecimal("100"), 2, java.math.RoundingMode.HALF_UP);
        return new InterestResponse(req.accountId, interest);
    }
}

// ─── Would be in service/InterestServiceV2.java (SHADOW) ───
class InterestServiceV2 {
    private final IsolatedLedger ledger; private final NoOpNotifier notifier;
        InterestServiceV2(IsolatedLedger ledger, NoOpNotifier notifier) { this.ledger = ledger;
        this.notifier = notifier; }
    InterestResponse compute(InterestRequest req) {
        BigDecimal interest = req.principal.multiply(req.ratePct)
                .divide(new BigDecimal("100"), 2, java.math.RoundingMode.HALF_UP);
        // DELIBERATE subtle bug: V2 mishandles a zero principal (returns 1 instead of 0).
        if (req.principal.compareTo(BigDecimal.ZERO) == 0) interest = new BigDecimal("1.00");
        ledger.record(req.accountId, interest); // ISOLATED ledger — no real posting
        notifier.send(req.accountId);           // NO-OP — no real notification
        return new InterestResponse(req.accountId, interest);
    }
}

// ─── Would be in shadow/IsolatedLedger.java ───
class IsolatedLedger {
    private static final Logger log = Logger.getLogger("Shadow");
    void record(String accountId, BigDecimal interest) {
        log.fine(() -> "[shadow-ledger ISOLATED] " + accountId + " interest=" + interest + " (NOT real)");
    }
}

// ─── Would be in shadow/NoOpNotifier.java ───
class NoOpNotifier {
    void send(String accountId) { /* intentionally does nothing — shadow must not notify */ }
}

// ─── Would be in shadow/TrafficDiffer.java ───
class TrafficDiffer {
    private static final Logger log = Logger.getLogger("Shadow");
    private int matches = 0; private int mismatches = 0;
    void compare(InterestResponse live, InterestResponse shadow) {
            if (live.equals(shadow)) { matches++;
            log.fine(() -> "match " + live); }
            else { mismatches++;
            log.warning(() -> "MISMATCH live=" + live + " shadow=" + shadow); }
    }
    int getMatches() { return matches; }
    int getMismatches() { return mismatches; }
}

// ─── Would be in core/MirroringGateway.java ───
class MirroringGateway {
    private static final Logger log = Logger.getLogger("Shadow");
    private final InterestServiceV1 live = new InterestServiceV1();
    private final InterestServiceV2 shadow = new InterestServiceV2(new IsolatedLedger(), new NoOpNotifier());
    private final TrafficDiffer differ = new TrafficDiffer();

    InterestResponse handle(InterestRequest req) {
        // 1) live path: compute and (in real system) write real ledger — this is returned.
        InterestResponse liveResp = live.compute(req);
        log.info(() -> "LIVE served " + liveResp);
        // 2) shadow path: fire-and-forget copy; response discarded for the client.
        mirrorAsync(req, liveResp);
        // 3) return ONLY the live response.
        return liveResp;
    }

    private void mirrorAsync(InterestRequest req, InterestResponse liveResp) {
        // fire-and-forget: a slow shadow must never delay the real response.
        java.util.concurrent.CompletableFuture.runAsync(() -> {
            try {
                InterestResponse shadowResp = shadow.compute(req); // isolated side effects
                differ.compare(liveResp, shadowResp);              // async traffic diff
            } catch (Exception e) {
                log.warning(() -> "shadow error (ignored, no user impact): " + e.getMessage());
            }
        });
    }

    void report() {
        // small wait so async mirrors finish before reporting (demo only)
        try { Thread.sleep(200); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        log.info(() -> "Shadow diff: matches=" + differ.getMatches() + " mismatches=" + differ.getMismatches());
    }
}

